L24_1.m_Pos = "C"
L24_1.m_Talk_KOREA = "다행인 점은, 우린 이미 녀석의 심장을 한 차례 꿰뚫는데 성공했다는 거지."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "幸いなことに、アタシたちはすでにあいつの心臓を一度、撃ち抜くことに成功したわ。"
L24_1.m_Talk_ENG = "Luckily, we have already succeeded in striking her heart once."
L24_1.m_Talk_TWN = "幸運的是，我們已經成功刺穿她的心臟一次。"
L24_1.m_Talk_SCN = "幸运的是，我们已经成功刺穿了她的心脏一次。"
L24_1.m_Talk_DEU = "Luckily, we have already succeeded in striking her heart once."
L24_1.m_Talk_FRA = "Luckily, we have already succeeded in striking her heart once."
