L48_1 = "고깃덩어리처럼 매달려, 적에게 자기 심장을 쥐여진 기분은 어떤가요?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "肉の塊のようにぶら下がり、敵に自分の心臓を握られている気分はどうですか？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "How does it feel to be hung like a slab of meat while your adversary grips your heart?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "像塊肉一樣被掛著，被敵人握住心臟的感覺如何？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "像块肉一样被挂着，被敌人握住心脏的感觉如何？"
L47_1.m_Talk_SCN = L48_1
L48_1 = "How does it feel to be hung like a slab of meat while your adversary grips your heart?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "How does it feel to be hung like a slab of meat while your adversary grips your heart?"
L47_1.m_Talk_FRA = L48_1
