L17_1 = "덕분에 세계의 경계가 허물어졌고, 악마들은 저 너머의 낙원을 침범할 수 있게 됐지."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "世界の境界が崩れ、悪魔たちは楽園を侵すことができるようになったわ。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "The boundaries between worlds have fallen, allowing devils to invade the Promised Land beyond."
L16_1.m_Talk_ENG = L17_1
L17_1 = "多虧如此，世界的邊界被打破，魔鬼們得以侵入彼岸的樂園。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "多亏如此，世界的边界被打破，恶魔们得以侵入彼岸的乐园。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "The boundaries between worlds have fallen, allowing devils to invade the Promised Land beyond."
L16_1.m_Talk_DEU = L17_1
L17_1 = "The boundaries between worlds have fallen, allowing devils to invade the Promised Land beyond."
L16_1.m_Talk_FRA = L17_1
