L17_1.m_fTalkTime = 0.03
L18_1 = "でも、私たち悪魔が自由になったとしても、その存在の根源はあくまでもこの世界。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Nevertheless, even if we devils are free, the basis of our existence is tied to this world."
L17_1.m_Talk_ENG = L18_1
L18_1 = "但是，就算魔鬼獲得了自由，我們存在的根基依然在這個世界。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "但是，即使恶魔获得了自由，我们存在的根基依然在这个世界。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Nevertheless, even if we devils are free, the basis of our existence is tied to this world."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Nevertheless, even if we devils are free, the basis of our existence is tied to this world."
L17_1.m_Talk_FRA = L18_1
