L30_1 = "AVENGER_ACT5_EPILOGUE@229#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 229
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 6600507
