L29_1.m_Face = "UNIT_DESPAIR"
L29_1.m_CharStrID = "MERLIN_ROOT_NULL_NULL"
L29_1.m_Pos = "C"
L30_1 = "긴 시간이 흘러, 넌 텅 빈 세계의 지하 밑바닥에서 홀로 눈을 뜨게 될 거야."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "長い時を経て、アナタは空っぽになった世界の地下、その底で一人目覚めることになる。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Ages will pass, and you will open your eyes in the depths of an empty world, alone."
L29_1.m_Talk_ENG = L30_1
L30_1 = "經過漫長的時間，你將在空虛的世界底下深處獨自醒來。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "经过漫长的时间，你将在空虚的世界底下深处独自醒来。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Ages will pass, and you will open your eyes in the depths of an empty world, alone."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Ages will pass, and you will open your eyes in the depths of an empty world, alone."
L29_1.m_Talk_FRA = L30_1
