L31_1 = "AVENGER_ACT5_EPILOGUE@230#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 230
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 6600507
L30_1.m_CutScenStrID = "AVENGER_ACT5_EPILOGUE"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "MERLIN_ROOT_NULL_NULL"
L30_1.m_Pos = "C"
L31_1 = "외로움에 굶주려 망가진 자매를 다시 빚어내겠지만, 인간성을 잃은 넌 아무 감정도 느끼지 못해."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "寂しさゆえに壊れたアナタが再び姉妹を作ったとしても、人間性を失ったせいで感情を抱くことができない。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Craving company, you will try to recreate your broken sister, but you will be unable to feel any emotion for you have lost all your humanity."
L30_1.m_Talk_ENG = L31_1
L31_1 = "你會在孤獨中重塑破碎的姐妹，但失去人性的你將無法感受到任何情感。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "你会在孤独中重塑破碎的姐妹，但失去人性的你将无法感受到任何情感。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Craving company, you will try to recreate your broken sister, but you will be unable to feel any emotion for you have lost all your humanity."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Craving company, you will try to recreate your broken sister, but you will be unable to feel any emotion for you have lost all your humanity."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "AVENGER_ACT5_EPILOGUE@231#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 231
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 6600507
L31_1.m_CutScenStrID = "AVENGER_ACT5_EPILOGUE"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_SERIOUS"
L31_1.m_CharStrID = "MERLIN_ROOT_NULL_NULL"
L31_1.m_Pos = "C"
L32_1 = "재회의 기쁨도, 소유의 만족도, 그리움에 대한 해소도, 그 무엇도 느끼지 못한 채…"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "再会の喜びも、所有することへの満足感も、寂しさの解消も、何も感じられないまま……"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Unable to feel the joy of reunion, the satisfaction of ownership, the relief of longing, or anything at all..."
L31_1.m_Talk_ENG = L32_1
L32_1 = "無論是重逢的喜悅，擁有的滿足，還是對思念的解脫，你都無法感受到…"
L31_1.m_Talk_TWN = L32_1
L32_1 = "无论是重逢的喜悦，拥有的满足，还是对思念的解脱，你都无法感受到……"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Unable to feel the joy of reunion, the satisfaction of ownership, the relief of longing, or anything at all..."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Unable to feel the joy of reunion, the satisfaction of ownership, the relief of longing, or anything at all..."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "AVENGER_ACT5_EPILOGUE@232#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 232
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 6600507
L32_1.m_CutScenStrID = "AVENGER_ACT5_EPILOGUE"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "MERLIN_ROOT_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "그저 외로움과 공허한 복수심만 남아, 영원히 어둠 속에서 살아가겠지."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "ただ寂しさと虚しい復讐心だけを抱えて、永遠に闇の中で生きていくでしょう。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Only loneliness and an empty desire for vengeance will remain as you live in darkness for eternity."
L32_1.m_Talk_ENG = L33_1
L33_1 = "只剩下孤獨和空虛的復仇心，永遠在黑暗中生存。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "只剩下孤独和空虚的复仇心，永远在黑暗中生存。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Only loneliness and an empty desire for vengeance will remain as you live in darkness for eternity."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Only loneliness and an empty desire for vengeance will remain as you live in darkness for eternity."
L32_1.m_Talk_FRA = L33_1
