L8_1 = "AB_UI_UNIT_VOICE_NKM_OPR_ROOT_DRUID_IN_STORY_24"
L7_1.m_VoiceFileName = L8_1
L8_1 = "돌아온 그루터기는 한없이 고요했다."
L7_1.m_Talk_KOREA = L8_1
L8_1 = 0.09
L7_1.m_fTalkTime = L8_1
L8_1 = "m_bTalkCenterFadeIn"
L7_1[L8_1] = true
L8_1 = "戻ってきた切り株は静寂に包まれていた。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Returning to the Stump, it was infinitely quiet."
L7_1.m_Talk_ENG = L8_1
L8_1 = "回到木墩的路途無比寂靜。"
