L9_1 = "AVENGER_ACT5_EPILOGUE@258#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 258
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 6600507
L8_1.m_CutScenStrID = "AVENGER_ACT5_EPILOGUE"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "AB_UI_UNIT_VOICE_NKM_OPR_ROOT_DRUID_IN_STORY_25"
L8_1.m_VoiceFileName = L9_1
L9_1 = "붉게 얼룩진 비탈길을 오르며, 죽어간 이들의 이름을 그 자리에 묻는다."
L8_1.m_Talk_KOREA = L9_1
L9_1 = 0.09
L8_1.m_fTalkTime = L9_1
L9_1 = "m_bTalkCenterFadeIn"
L8_1[L9_1] = true
L9_1 = "赤く染まった坂道を登りながら、死んでいった彼らの名前を偲ぶ。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Walking up the blood-soaked slope, I bury the names of those who have fallen."
L8_1.m_Talk_ENG = L9_1
L9_1 = "沿著染紅的斜坡前行，我將逝者的名字埋葬在那片土地上。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "沿着染红的斜坡前行，我将逝者的名字埋葬在那片土地上。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Walking up the blood-soaked slope, I bury the names of those who have fallen."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Walking up the blood-soaked slope, I bury the names of those who have fallen."
L8_1.m_Talk_FRA = L9_1
