L10_1 = "AVENGER_ACT5_EPILOGUE@259#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 259
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 6600507
L9_1.m_CutScenStrID = "AVENGER_ACT5_EPILOGUE"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "AB_UI_UNIT_VOICE_NKM_OPR_ROOT_DRUID_IN_STORY_26"
L9_1.m_VoiceFileName = L10_1
L10_1 = "이윽고 둔덕에 다다랐을 때 두 눈에 담긴 광경은, 참혹하면서도 아련한 것이었다."
L9_1.m_Talk_KOREA = L10_1
L10_1 = 0.09
L9_1.m_fTalkTime = L10_1
L10_1 = "m_bTalkCenterFadeIn"
L9_1[L10_1] = true
L10_1 = "やがて丘に着いたとき、両目に映った光景は、惨烈であり茫茫たるものであった。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "As I approached the mound, the sight before my eyes was cruel and sorrowful."
L9_1.m_Talk_ENG = L10_1
L10_1 = "到達山丘時，映入眼簾的是既慘烈又令人悲傷的景象。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "到达山丘时，映入眼帘的是既惨烈又令人悲伤的景象。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "As I approached the mound, the sight before my eyes was cruel and sorrowful."
L9_1.m_Talk_DEU = L10_1
L10_1 = "As I approached the mound, the sight before my eyes was cruel and sorrowful."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "AVENGER_ACT5_EPILOGUE@260#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 260
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 6600507
