L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "AB_UI_UNIT_VOICE_NKM_OPR_ROOT_DRUID_IN_STORY_27"
L10_1.m_VoiceFileName = L11_1
L11_1 = "떠나갈 아이들을 지키기 위해 마지막까지 분전한 저항의 흔적이, 낙원문을 드넓게 에워싸고 있었다."
L10_1.m_Talk_KOREA = L11_1
L11_1 = 0.09
L10_1.m_fTalkTime = L11_1
L11_1 = "m_bTalkCenterFadeIn"
